function minimizeStringValue(s) {
  const count = new Array(26).fill(0);
  for (const ch of s) {
    if (ch !== '?') {
      count[ch.charCodeAt(0) - 97]++;
    }
  }

  const added = [];
  for (const ch of s) {
    if (ch !== '?') {
      continue;
    }
    let best = 0;
    for (let letter = 1; letter < 26; letter++) {
      if (count[letter] < count[best]) {
        best = letter;
      }
    }
    count[best]++;
    added.push(best);
  }
  added.sort((a, b) => a - b);

  const result = [];
  let next = 0;
  for (const ch of s) {
    if (ch === '?') {
      result.push(String.fromCharCode(97 + added[next]));
      next++;
    } else {
      result.push(ch);
    }
  }
  return result.join('');
}

