function minimizeStringValue(s) {
  const counts = new Array(26).fill(0);
  let q = 0;
  for (const ch of s) if (ch === '?') q++; else counts[ch.charCodeAt(0) - 97]++;
  // Smallest value reachable by adding exactly extra letters on top of cnt: an exact knapsack over the 26 letters.
  const least = (cnt, extra) => {
    let dp = new Array(extra + 1).fill(Infinity);
    dp[0] = 0;
    for (let l = 0; l < 26; l++) {
      const nd = new Array(extra + 1).fill(Infinity);
      for (let used = 0; used <= extra; used++) {
        if (dp[used] === Infinity) continue;
        for (let add = 0; used + add <= extra; add++) {
          const c = cnt[l] + add;
          nd[used + add] = Math.min(nd[used + add], dp[used] + c * (c - 1) / 2);
        }
      }
      dp = nd;
    }
    return dp[extra];
  };
  const target = least(counts, q);
  // Fill the '?' from left to right with the smallest letter that still allows the optimal value.
  const chars = s.split('');
  let left = q;
  for (let i = 0; i < chars.length; i++) {
    if (chars[i] !== '?') continue;
    left--;
    for (let l = 0; l < 26; l++) {
      counts[l]++;
      if (least(counts, left) === target) { chars[i] = String.fromCharCode(97 + l); break; }
      counts[l]--;
    }
  }
  return chars.join('');
}

