function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (size === 'large') {
    const n = 10000;
    const density = [0.05, 0.5, 0.95, 1][int(0, 3)];
    const alphabet = int(1, 26);
    let s = '';
    for (let i = 0; i < n; i++) s += rand() < density ? '?' : letters[int(0, alphabet - 1)];
    return [s];
  }
  const shape = int(0, 2);
  const chars = [];
  if (shape === 0) {
    const alphabet = int(1, 4);
    for (let i = int(0, 7); i > 0; i--) chars.push(letters[int(0, alphabet - 1)]);
  } else {
    // Most or all of the alphabet already present, so the '?' choices must break ties among used letters.
    const skip = shape === 1 ? -1 : int(0, 25);
    for (let i = 0; i < 26; i++) if (i !== skip) chars.push(letters[i]);
    for (let i = int(0, 3); i > 0; i--) chars.push(letters[int(0, 25)]);
  }
  const marks = int(chars.length ? 0 : 1, 8);
  for (let i = 0; i < marks; i++) chars.push('?');
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
